#!/usr/bin/env python3
"""COSMOS v9.5.6.4 guarded OneTouch popup and labeled-moments update.
Run from repository root: python3 scripts/apply_cosmos_onetouch_v9564.py --mode validate|apply|rollback
Only cosmos-next.html is modified, not the Worker, database, or legal documents.
"""
import argparse,base64,gzip,os,subprocess,tempfile
from pathlib import Path
SOURCE=Path('cosmos-next.html')
PATCH_GZ_B64=''
BASE_MARKERS=("version:'9.5.6.3'",'cosmosOneTouchBridgeV9563','v9.5.6.3: a small month compass','cosmos953LegalStatusNeeded')
NEW_MARKERS=("version:'9.5.6.4'",'v9.5.6.4: OneTouch is the only default UI',"co-feature-dismiss",'co-station-icon','function previewStation(item)')

def state(content):
    has_new=[x in content for x in NEW_MARKERS]
    if any(has_new) and not all(has_new):raise ValueError('Partial v9.5.6.4 installation detected. Stop and inspect current code.')
    return 'installed' if all(has_new) else 'baseline'

def syntax(content):
    markers=['<script>\n(() => {','<script id="cosmos-v956-js">']
    for i,marker in enumerate(markers):
        where=content.find(marker)
        if where<0:raise ValueError('Script entry marker missing: '+marker)
        close=content.find('</script>',where)
        if close<0:raise ValueError('Script not closed')
        skip=len('<script>') if marker.startswith('<script>') else len(marker)
        js=content[where+skip:close]
        with tempfile.TemporaryDirectory() as tmp:
            file=Path(tmp)/('app%d.js'%i);file.write_text(js,encoding='utf8')
            output=subprocess.run(['node','--check',str(file)],capture_output=True,text=True)
            if output.returncode:raise ValueError('JavaScript invalid: '+output.stderr[:1000])

def change(content,reverse=False):
    with tempfile.TemporaryDirectory() as tmp:
        folder=Path(tmp)
        (folder/'cosmos-next.html').write_text(content,encoding='utf8',newline='')
        patch=folder/'change.patch'
        patch.write_bytes(gzip.decompress(base64.b64decode(PATCH_GZ_B64)))
        cmd=['patch','--batch','--silent','--fuzz=0','-p0','-i',str(patch)]
        if reverse:cmd.insert(1,'--reverse')
        res=subprocess.run(cmd,cwd=folder,capture_output=True,text=True)
        if res.returncode:raise ValueError('Patch did not match your current cosmos-next.html. '+(res.stdout+res.stderr)[:500])
        return (folder/'cosmos-next.html').read_text(encoding='utf8')

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--mode',choices=['validate','apply','rollback'],default='validate')
    mode=parser.parse_args().mode
    if not SOURCE.is_file():raise SystemExit('Run from repository root where cosmos-next.html exists.')
    original=SOURCE.read_text(encoding='utf8')
    try:
        installed=state(original)=='installed'
        if not installed and not all(m in original for m in BASE_MARKERS):
            raise ValueError('Expected v9.5.6.3 frontend and legal repair markers not found.')
        if mode=='rollback':
            updated=change(original,reverse=True) if installed else original
        else:
            updated=original if installed else change(original)
            if state(updated)!='installed':raise ValueError('Updated code markers missing.')
        syntax(updated)
        if not installed and mode!='rollback' and change(updated,reverse=True)!=original:
            raise ValueError('Apply+rollback roundtrip failed.')
        if installed and mode=='rollback' and change(updated)!=original:
            raise ValueError('Rollback+apply roundtrip failed.')
    except ValueError as e:raise SystemExit('BLOCKED — '+str(e))
    print('PASS — COSMOS v9.5.6.4: syntax, compatibility, apply/rollback tests.')
    print('Updated:', updated!=original, 'Installed:', state(updated)=='installed')
    if mode=='validate' or updated==original:return
    staged=SOURCE.with_suffix('.v9564.tmp')
    staged.write_text(updated,encoding='utf8',newline='')
    os.replace(staged,SOURCE)
    print('UPDATED cosmos-next.html (frontend only).')
if __name__=='__main__':main()
